-- Switch: mcp_write_settings.writes_enabled (one row, default false), a new table on which no API role (anon,
--   authenticated, service_role) holds any privilege, so only the database owner turns it on:
--   UPDATE public.mcp_write_settings SET writes_enabled = true WHERE id;  (mcp_settings.enabled must be on too)
--   While it is off: a new consent grants 'mcp:read' only and shows read-only wording; mcp_write_access answers
--   write:false; every write tool answers read_only and writes nothing; get_deal_checklists keeps frame v1.
-- Scope: mcp_authorization_requests.scope and mcp_connections.scope accept 'mcp:read' and 'mcp:todos'. No row is
--   changed. A connection is never upgraded: its scope is set once, at consent, and refresh keeps it. Writes need
--   scope 'mcp:todos' AND the switch on, checked inside every write function.
-- Replaced (pre-check below; each body differs from the traced one only where its comment says):
--   anon       mcp_authorize_begin   accepts 'mcp:todos'; records it only when asked for AND the switch is on
--              mcp_exchange_code     answers the connection's scope
--              mcp_refresh           answers the connection's scope
--   signed in  mcp_authorize_view    scope = what approve would grant now
--              mcp_authorize_approve grants 'mcp:todos' only when the request asked for it and the switch is on
--   reader     _mcp_r_deal_checklists (owner mcp_reader) frame v2 while the switch is on: due_date, note_complete,
--              editable_title, removable on each item; frame v1, byte for byte, while it is off
-- New:
--   anon       mcp_write_access, mcp_update_todo, mcp_add_todo, mcp_remove_todo, mcp_restore_todo
--              (each takes the portal secret and the access token digest; intentionally callable by anon)
--   internal   _mcp_writes_on (SECURITY DEFINER, EXECUTE mcp_reader only), _mcp_granted_scope,
--              _mcp_conn_can_write, _mcp_todo_item_out, _mcp_todo_call (no API role)
--   checks     mcp_call_log tool and outcome CHECKs widened (found by column, as 20261114110000 does)
-- Writes: every write tool is one call of _cloud_todo_apply (20261118110000) with actor
--   {kind 'ai_app', ref <connection id>, label from the provider}, inside one inner block that sets the owner's
--   claims transaction-locally and restores the three incoming settings before it ends. A tool call is all or
--   nothing: any part refused rolls back every part of that call. The call log row and the counters stay.
-- Lock order: as 20261118110000 (settings, the owner's feed head, deals, checklists, items, by id), through the
--   core only; _mcp_enter's connection row update comes first, as for every MCP call.
-- Tables: mcp_write_settings (RLS on, no policy, ALL revoked from PUBLIC, anon, authenticated and service_role).
-- Re-runnable: CREATE TABLE IF NOT EXISTS, CHECKs found by column, CREATE OR REPLACE; the switch keeps its value.
-- Rollback: supabase/tests/backlog-4263-pr5/rollback-20261118130000.sql
-- ============================================================================

DO $precheck4263p5$
DECLARE r record; v_md5 text; v_src text;
BEGIN
  FOR r IN SELECT * FROM (VALUES
      ('public.mcp_authorize_begin(text,text,text,text,text,text,text,text,bytea,bytea)', 'bf7192517604c2db532312a7e071a751'),
      ('public.mcp_authorize_view(text,bytea)', '879b6c01072494b931e782a6f07b463d'),
      ('public.mcp_authorize_approve(text,bytea,text,bytea)', '90eac2594c015edc44b3fecc9ec0209b'),
      ('public.mcp_exchange_code(text,bytea,text,text,text,text,bytea,bytea)', 'cfb0787d8601435bbe47a575155866b8'),
      ('public.mcp_refresh(text,bytea,text,text,bytea,bytea)', 'b6ccefaa100e0b69df3e16e0a407d740'),
      ('public._mcp_r_deal_checklists(uuid,boolean,uuid)', 'f6a9f0336a1a070adcf66778afecbce7')
    ) x(sig, md5) LOOP
    SELECT md5(p.prosrc), p.prosrc INTO v_md5, v_src FROM pg_catalog.pg_proc p WHERE p.oid = to_regprocedure(r.sig);
    IF v_md5 IS DISTINCT FROM r.md5 AND position('/*BODY:4263-5*/' IN coalesce(v_src, '')) = 0 THEN
      RAISE EXCEPTION 'BACKLOG-4263 PR-5: % is not at the traced body (md5 %)', r.sig, coalesce(v_md5, 'missing');
    END IF;
  END LOOP;
  -- the core this file writes through, at the body 20261118110000 wrote
  FOR r IN SELECT * FROM (VALUES
      ('public._cloud_todo_apply(uuid,jsonb,jsonb)', '015f9e647e988e6c81791d9ee4e6750f'),
      ('public._cloud_todo_apply_op(uuid,jsonb,text,uuid,jsonb,timestamp with time zone)', '5b0df6658b9681c281bc64fd8fbc7846')
    ) x(sig, md5) LOOP
    SELECT md5(p.prosrc) INTO v_md5 FROM pg_catalog.pg_proc p WHERE p.oid = to_regprocedure(r.sig);
    IF v_md5 IS DISTINCT FROM r.md5 THEN
      RAISE EXCEPTION 'BACKLOG-4263 PR-5: % is not at the body 20261118110000 wrote (md5 %)', r.sig, coalesce(v_md5, 'missing');
    END IF;
  END LOOP;
END
$precheck4263p5$;

-- ============================================================================ switch, scope, call log
CREATE TABLE IF NOT EXISTS public.mcp_write_settings (
  id             boolean PRIMARY KEY DEFAULT true CHECK (id),
  writes_enabled boolean NOT NULL DEFAULT false,
  updated_at     timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.mcp_write_settings ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.mcp_write_settings FROM PUBLIC, anon, authenticated, service_role;
INSERT INTO public.mcp_write_settings (id) VALUES (true) ON CONFLICT (id) DO NOTHING;

DO $scope4263p5$
DECLARE v_tab regclass; v_name text;
BEGIN
  FOREACH v_tab IN ARRAY ARRAY['public.mcp_authorization_requests'::regclass, 'public.mcp_connections'::regclass] LOOP
    FOR v_name IN
      SELECT c.conname FROM pg_catalog.pg_constraint c
       WHERE c.conrelid = v_tab AND c.contype = 'c'
         AND c.conkey = ARRAY[(SELECT a.attnum FROM pg_catalog.pg_attribute a WHERE a.attrelid = v_tab AND a.attname = 'scope')]
    LOOP
      EXECUTE format('ALTER TABLE %s DROP CONSTRAINT %I', v_tab, v_name);
    END LOOP;
  END LOOP;
END
$scope4263p5$;
ALTER TABLE public.mcp_authorization_requests ADD CONSTRAINT mcp_authorization_requests_scope_check
  CHECK (scope IN ('mcp:read', 'mcp:todos'));
ALTER TABLE public.mcp_connections ADD CONSTRAINT mcp_connections_scope_check
  CHECK (scope IN ('mcp:read', 'mcp:todos'));

DO $chk4263p5$
DECLARE v_name text;
BEGIN
  FOR v_name IN
    SELECT c.conname FROM pg_catalog.pg_constraint c
     WHERE c.conrelid = 'public.mcp_call_log'::regclass AND c.contype = 'c'
       AND c.conkey IN (ARRAY[(SELECT a.attnum FROM pg_catalog.pg_attribute a WHERE a.attrelid = 'public.mcp_call_log'::regclass AND a.attname = 'tool')],
                        ARRAY[(SELECT a.attnum FROM pg_catalog.pg_attribute a WHERE a.attrelid = 'public.mcp_call_log'::regclass AND a.attname = 'outcome')])
  LOOP
    EXECUTE format('ALTER TABLE public.mcp_call_log DROP CONSTRAINT %I', v_name);
  END LOOP;
END
$chk4263p5$;
ALTER TABLE public.mcp_call_log ADD CONSTRAINT mcp_call_log_tool_check
  CHECK (tool IS NULL OR tool IN ('get_status', 'list_deals', 'get_deal', 'get_deal_checklists', 'list_all_deals',
                                  'update_todo', 'add_todo', 'remove_todo', 'restore_todo'));
ALTER TABLE public.mcp_call_log ADD CONSTRAINT mcp_call_log_outcome_check
  CHECK (outcome IN ('pending', 'ok', 'not_connected', 'disabled', 'rate_limited', 'busy', 'not_entitled', 'timeout', 'error',
                     'invalid_input', 'not_found', 'too_large', 'read_only', 'refused'));

-- ============================================================================ internal helpers
-- True while MCP is on and the write switch is on. SECURITY DEFINER so the reader (owner mcp_reader, which has no
-- privilege on either table) can choose its frame; it returns one boolean and takes no argument.
CREATE OR REPLACE FUNCTION public._mcp_writes_on()
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $fn$
  SELECT coalesce((SELECT s.enabled FROM public.mcp_settings s WHERE s.id), false)
     AND coalesce((SELECT w.writes_enabled FROM public.mcp_write_settings w WHERE w.id), false)   /*SWITCH:read*/
$fn$;
REVOKE ALL ON FUNCTION public._mcp_writes_on() FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public._mcp_writes_on() TO mcp_reader;

-- The scope a consent grants now for a request that asked for p_requested.
CREATE OR REPLACE FUNCTION public._mcp_granted_scope(p_requested text)
RETURNS text LANGUAGE sql STABLE SECURITY INVOKER SET search_path = '' AS $fn$
  SELECT CASE WHEN p_requested = 'mcp:todos' AND public._mcp_writes_on() THEN 'mcp:todos' ELSE 'mcp:read' END   /*SCOPE:grant*/
$fn$;
REVOKE ALL ON FUNCTION public._mcp_granted_scope(text) FROM PUBLIC, anon, authenticated, service_role;

-- True when this active connection was granted 'mcp:todos' and the switch is on.
CREATE OR REPLACE FUNCTION public._mcp_conn_can_write(p_connection_id uuid)
RETURNS boolean LANGUAGE sql STABLE SECURITY INVOKER SET search_path = '' AS $fn$
  SELECT public._mcp_writes_on()                                                                   /*WRITE:switch*/
     AND EXISTS (SELECT 1 FROM public.mcp_connections c
                  WHERE c.id = p_connection_id AND c.status = 'active' AND c.scope = 'mcp:todos')   /*WRITE:scope*/
$fn$;
REVOKE ALL ON FUNCTION public._mcp_conn_can_write(uuid) FROM PUBLIC, anon, authenticated, service_role;

-- One todo as a write tool returns it (the item keys of get_deal_checklists frame v2, plus deal_id, checklist_id and
-- removed), or NULL when the owner has no such item on a confirmed deal, or it was purged.
CREATE OR REPLACE FUNCTION public._mcp_todo_item_out(p_owner uuid, p_item uuid)
RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path = '' AS $fn$
  SELECT jsonb_build_object(
           'item_id', t.id,
           'deal_id', t.cloud_deal_id,
           'checklist_id', t.cloud_checklist_id,
           'title', public._mcp_clean(t.title, 300),
           'required', t.is_required,
           'done', t.is_checked,
           'done_at', public._mcp_ts(t.checked_at),
           'note', public._mcp_clean(t.note, 1000),
           'note_complete', t.note IS NULL OR public._mcp_clean(t.note, 1000) = t.note,
           'due_date', to_char(t.due_date, 'YYYY-MM-DD'),
           'editable_title', c.template_id = 'keepr:my-items',
           'removable', c.template_id = 'keepr:my-items',
           'removed', t.removed_at IS NOT NULL OR c.removed_at IS NOT NULL OR d.removed_at IS NOT NULL)
    FROM public.cloud_deal_checklist_items t
    JOIN public.cloud_deal_checklists c ON c.id = t.cloud_checklist_id AND c.owner_user_id = p_owner
    JOIN public.cloud_deals d ON d.id = t.cloud_deal_id AND d.owner_user_id = p_owner
   WHERE t.id = p_item AND t.owner_user_id = p_owner /*OWN:item_out*/ AND d.is_confirmed AND t.purged_at IS NULL AND c.purged_at IS NULL
$fn$;
REVOKE ALL ON FUNCTION public._mcp_todo_item_out(uuid, uuid) FROM PUBLIC, anon, authenticated, service_role;

-- The body of the four write tools. a: {item_id, changes, request_id} (update_todo), {deal_id, title, note,
-- due_date, request_id} (add_todo), {item_id, request_id} (remove_todo, restore_todo).
-- Returns {ok:true, result:{kind:'keepr.todo_change', v:1, about, status, item}}
--   status: applied | unchanged | added | already_added | removed | already_removed | restored | not_removed
--           (written, or nothing to write) | locked | not_allowed | is_removed | not_restorable | note_was_shortened
--           (refused; nothing written)
-- or {ok:false, error}: not_connected | disabled | rate_limited | busy | read_only | not_entitled | invalid_input |
--   not_found | timeout | error
-- Order: secret, token (_mcp_enter: connection, rate per connection and per user, call log row), write gate
-- (switch and scope), 500 writes per user per day, arguments, then the inner block.
-- request_id: a retried call with the same request_id and the same arguments gets the same op ids, so the core's
-- ledger answers it with the stored result and writes nothing.
CREATE OR REPLACE FUNCTION public._mcp_todo_call(p_secret text, p_at_digest bytea, p_resource text, p_tool text, a jsonb)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path = '' AS $fn$
DECLARE
  g       public.mcp_gate;
  v_t0    timestamptz := clock_timestamp();
  v_b     text;
  v_uuid  text := '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$';
  v_item  uuid;
  v_deal  uuid;
  v_req   text := a ->> 'request_id';
  v_ch    jsonb := a -> 'changes';
  v_ops   jsonb := '[]'::jsonb;
  v_key   text;
  v_op    jsonb;
  v_note_op uuid;
  v_res   jsonb;
  v_r     jsonb;
  v_st    text;
  v_first text;
  v_wrote integer := 0;
  v_any   boolean := false;
  v_c0    text;
  v_s0    text;
  v_r0    text;
  v_lt0   text;
  v_old   jsonb;
  v_order integer;
  v_out   text;
  v_frame jsonb;
BEGIN
  IF public._mcp_secret_ok(p_secret) IS NOT TRUE THEN
    RETURN public._mcp_refuse('not_connected');
  END IF;
  g := public._mcp_enter(p_at_digest, p_resource, p_tool);
  IF g.outcome IS DISTINCT FROM 'ok' THEN
    RETURN public._mcp_refuse(g.outcome);
  END IF;
  IF public._mcp_conn_can_write(g.connection_id) IS NOT TRUE THEN                                  /*WRITE:gate*/
    PERFORM public._mcp_finish(g.call_id, 'read_only', 0, v_t0);
    RETURN public._mcp_refuse('read_only');
  END IF;
  v_b := public._mcp_bump('todo_write_user:' || g.user_id::text, interval '1 day', 500);          /*WRITE:day*/
  IF v_b IS DISTINCT FROM 'ok' THEN
    PERFORM public._mcp_finish(g.call_id, coalesce(v_b, 'busy'), 0, v_t0);
    RETURN public._mcp_refuse(coalesce(v_b, 'busy'));
  END IF;

  -- ---------------------------------------------------------------- arguments
  IF (jsonb_typeof(a -> 'request_id') IN ('null') OR a -> 'request_id' IS NULL
      OR (jsonb_typeof(a -> 'request_id') = 'string' AND v_req ~ '^[A-Za-z0-9._:-]{1,100}$')) IS NOT TRUE THEN   /*ARG:request_id*/
    v_first := 'invalid_input';
  ELSIF p_tool IN ('update_todo', 'remove_todo', 'restore_todo') THEN
    IF ((a ->> 'item_id') ~ v_uuid) IS NOT TRUE THEN                                                  /*ARG:item_id*/
      v_first := 'invalid_input';
    ELSE
      v_item := (a ->> 'item_id')::uuid;
    END IF;
  ELSIF p_tool = 'add_todo' THEN
    IF ((a ->> 'deal_id') ~ v_uuid) IS NOT TRUE                                                       /*ARG:deal_id*/
       OR (jsonb_typeof(a -> 'title') = 'string' AND char_length(a ->> 'title') <= 2000) IS NOT TRUE   /*ARG:add_title*/
       OR (jsonb_typeof(a -> 'note') = 'null' OR a -> 'note' IS NULL
           OR (jsonb_typeof(a -> 'note') = 'string' AND char_length(a ->> 'note') <= 16000)) IS NOT TRUE   /*ARG:add_note*/
       OR (jsonb_typeof(a -> 'due_date') = 'null' OR a -> 'due_date' IS NULL
           OR (jsonb_typeof(a -> 'due_date') = 'string' AND (a ->> 'due_date') ~ '^\d{4}-\d{2}-\d{2}$')) IS NOT TRUE THEN   /*ARG:add_due*/
      v_first := 'invalid_input';
    ELSE
      v_deal := (a ->> 'deal_id')::uuid;
    END IF;
  ELSE
    v_first := 'invalid_input';
  END IF;
  IF v_first IS NULL AND p_tool = 'update_todo' THEN
    IF (jsonb_typeof(v_ch) = 'object' AND v_ch <> '{}'::jsonb
        AND NOT EXISTS (SELECT 1 FROM jsonb_object_keys(v_ch) k WHERE k NOT IN ('done', 'title', 'note', 'due_date'))     /*ARG:changes_keys*/
        AND (NOT v_ch ? 'done' OR jsonb_typeof(v_ch -> 'done') = 'boolean')
        AND (NOT v_ch ? 'title' OR (jsonb_typeof(v_ch -> 'title') = 'string' AND char_length(v_ch ->> 'title') <= 2000))
        AND (NOT v_ch ? 'note' OR jsonb_typeof(v_ch -> 'note') = 'null'
             OR (jsonb_typeof(v_ch -> 'note') = 'string' AND char_length(v_ch ->> 'note') <= 16000))
        AND (NOT v_ch ? 'due_date' OR jsonb_typeof(v_ch -> 'due_date') = 'null'
             OR (jsonb_typeof(v_ch -> 'due_date') = 'string' AND (v_ch ->> 'due_date') ~ '^\d{4}-\d{2}-\d{2}$'))) IS NOT TRUE THEN
      v_first := 'invalid_input';
    END IF;
  END IF;
  IF v_first IS NOT NULL THEN
    PERFORM public._mcp_finish(g.call_id, v_first, 0, v_t0);
    RETURN public._mcp_refuse(v_first);
  END IF;

  -- ---------------------------------------------------------------- ops (op ids from request_id when given)
  IF p_tool = 'update_todo' THEN
    FOREACH v_key IN ARRAY ARRAY['done', 'title', 'note', 'due_date'] LOOP
      CONTINUE WHEN NOT v_ch ? v_key;
      v_op := jsonb_build_object(
        'op_id', CASE WHEN v_req IS NULL THEN gen_random_uuid()
                      ELSE md5(concat_ws('|', 'mcp-todo', g.connection_id::text, p_tool, v_key, a::text))::uuid END,   /*REPLAY:op_id*/
        'kind', 'set', 'entity', 'item', 'id', v_item,
        'part', CASE v_key WHEN 'due_date' THEN 'due' ELSE v_key END,
        'value', v_ch -> v_key);
      IF v_key = 'note' THEN v_note_op := (v_op ->> 'op_id')::uuid; END IF;
      v_ops := v_ops || jsonb_build_array(v_op);
    END LOOP;
  ELSE
    v_op := jsonb_build_object(
      'op_id', CASE WHEN v_req IS NULL THEN gen_random_uuid()
                    ELSE md5(concat_ws('|', 'mcp-todo', g.connection_id::text, p_tool, a::text))::uuid END,
      'kind', CASE p_tool WHEN 'add_todo' THEN 'create_item' WHEN 'remove_todo' THEN 'remove' ELSE 'restore' END);
    IF p_tool = 'add_todo' THEN
      v_op := v_op || jsonb_build_object('deal_id', v_deal, 'title', a -> 'title',
                                         'note', coalesce(a -> 'note', 'null'::jsonb), 'due_date', coalesce(a -> 'due_date', 'null'::jsonb));
    ELSE
      v_op := v_op || jsonb_build_object('entity', 'item', 'id', v_item);
    END IF;
    v_ops := jsonb_build_array(v_op);
  END IF;

  -- ---------------------------------------------------------------- the write: one block, the owner's claims inside only
  v_c0 := current_setting('request.jwt.claims', true);                                             /*CLAIMS:save*/
  v_s0 := current_setting('request.jwt.claim.sub', true);
  v_r0 := current_setting('request.jwt.claim.role', true);
  v_lt0 := current_setting('lock_timeout');
  BEGIN
    -- every lock wait in the block is bounded (the core's own head wait is 2 s too); a wait past it answers busy
    PERFORM set_config('lock_timeout', '2s', true);                                                /*LOCK:timeout*/
    PERFORM set_config('request.jwt.claims', jsonb_build_object('sub', g.user_id, 'role', 'authenticated')::text, true);
    PERFORM set_config('request.jwt.claim.sub', g.user_id::text, true);
    PERFORM set_config('request.jwt.claim.role', 'authenticated', true);
    IF p_tool = 'add_todo' THEN
      -- the next free place on the deal's live My items list, as the desktop adds one (0 for a new list)
      SELECT coalesce(max(t.sort_order) + 1, 0) INTO v_order                                       /*ADD:order*/
        FROM public.cloud_deal_checklist_items t
        JOIN public.cloud_deal_checklists c ON c.id = t.cloud_checklist_id
       WHERE c.cloud_deal_id = v_deal AND c.owner_user_id = g.user_id AND c.template_id = 'keepr:my-items'
         AND c.removed_at IS NULL AND c.purged_at IS NULL AND t.removed_at IS NULL AND t.purged_at IS NULL;
      v_ops := jsonb_build_array((v_ops -> 0) || jsonb_build_object('sort_order', v_order));
    END IF;
    v_res := public._cloud_todo_apply(g.user_id,
               jsonb_build_object('kind', 'ai_app', 'ref', g.connection_id::text,
                                  'label', CASE g.provider WHEN 'anthropic' THEN 'Claude' WHEN 'openai' THEN 'ChatGPT' END),   /*ACTOR:label*/
               v_ops);
    IF v_res ->> 'ok' IS DISTINCT FROM 'true' THEN
      v_first := CASE WHEN v_res ->> 'error' IN ('not_entitled', 'busy') THEN v_res ->> 'error' ELSE 'error' END;
      RAISE EXCEPTION USING ERRCODE = 'MC002', MESSAGE = 'mcp write refused';
    END IF;
    FOR v_r IN SELECT x FROM jsonb_array_elements(v_res -> 'results') x LOOP
      v_st := v_r ->> 'status';
      IF v_st IN ('applied', 'added', 'removed', 'restored') THEN
        v_wrote := v_wrote + 1; v_any := true;
      ELSIF v_st IN ('unchanged', 'already_added', 'already_removed', 'not_removed') THEN
        NULL;
      ELSE
        v_first := CASE WHEN v_st IN ('locked', 'not_allowed') THEN v_st
                        WHEN v_st = 'refused_removed' THEN 'is_removed'
                        WHEN v_st = 'not_restorable' AND p_tool = 'restore_todo' THEN 'not_restorable'
                        WHEN v_st IN ('not_found', 'not_restorable') THEN 'not_found'
                        WHEN v_st = 'rejected' THEN 'invalid_input'
                        ELSE 'error' END;
        RAISE EXCEPTION USING ERRCODE = 'MC002', MESSAGE = 'mcp write refused';                    /*WRITE:all_or_nothing*/
      END IF;
    END LOOP;
    -- a note the app could not have seen whole (shortened or masked when read) is not replaced
    IF v_note_op IS NOT NULL THEN
      SELECT h.old_value INTO v_old FROM public.cloud_todo_history h
       WHERE h.owner_user_id = g.user_id AND h.op_id = v_note_op AND h.part = 'note' AND h.kind = 'change' AND h.outcome = 'applied'
       ORDER BY h.id DESC LIMIT 1;
      IF jsonb_typeof(v_old) = 'string' AND public._mcp_clean(v_old #>> '{}', 1000) IS DISTINCT FROM (v_old #>> '{}') THEN   /*NOTE:shortened*/
        v_first := 'note_was_shortened';
        RAISE EXCEPTION USING ERRCODE = 'MC002', MESSAGE = 'mcp write refused';
      END IF;
    END IF;
    IF p_tool = 'add_todo' THEN
      v_item := (v_res -> 'results' -> 0 ->> 'cloud_id')::uuid;
    END IF;
    PERFORM set_config('request.jwt.claims', coalesce(v_c0, ''), true);                            /*CLAIMS:restore*/
    PERFORM set_config('request.jwt.claim.sub', coalesce(v_s0, ''), true);
    PERFORM set_config('request.jwt.claim.role', coalesce(v_r0, ''), true);
    PERFORM set_config('lock_timeout', v_lt0, true);                                               /*LOCK:restore*/
  EXCEPTION
    -- a failed block is rolled back with its claim settings; v_first says why
    WHEN SQLSTATE 'MC002' THEN NULL;
    WHEN lock_not_available THEN v_first := 'busy';
    -- _mcp_enter holds this connection's row; a turn-off holding the settings row then waits on it to disconnect
    -- the app. The write is the one that waited first, so it is the one refused; nothing of it is kept.
    WHEN deadlock_detected THEN v_first := 'busy';
    WHEN query_canceled THEN v_first := 'timeout';
    WHEN OTHERS THEN v_first := 'error';
  END;

  IF v_first IN ('not_connected', 'disabled', 'rate_limited', 'busy', 'read_only', 'not_entitled', 'invalid_input', 'not_found', 'timeout', 'error') THEN
    PERFORM public._mcp_finish(g.call_id, v_first, 0, v_t0);
    RETURN public._mcp_refuse(v_first);
  END IF;
  v_frame := jsonb_build_object(
    'kind', 'keepr.todo_change',
    'v', 1,
    'about', 'The answer to one change to a todo in the person''s Keepr account. status says what happened; locked, not_allowed, is_removed, not_restorable and note_was_shortened mean nothing was changed. item is the todo as it is now. Every change records this app''s name and shows in the Keepr desktop app.',
    'status', coalesce(v_first, CASE p_tool
                                  WHEN 'update_todo' THEN CASE WHEN v_any THEN 'applied' ELSE 'unchanged' END
                                  ELSE v_res -> 'results' -> 0 ->> 'status' END),
    'item', public._mcp_todo_item_out(g.user_id, v_item));
  PERFORM public._mcp_finish(g.call_id, CASE WHEN v_first IS NULL THEN 'ok' ELSE 'refused' END, CASE WHEN v_first IS NULL THEN v_wrote ELSE 0 END, v_t0);
  RETURN jsonb_build_object('ok', true, 'result', v_frame);
END
$fn$;
REVOKE ALL ON FUNCTION public._mcp_todo_call(text, bytea, text, text, jsonb) FROM PUBLIC, anon, authenticated, service_role;

-- ============================================================================ anon: write access and the four tools
-- Returns {ok:true, write:boolean} | {ok:false, error:'not_connected'}. Not counted, not logged. write is true only
-- for an active connection granted 'mcp:todos' while the switch is on; the portal lists the write tools only then.
-- Intentionally callable by anon: MCP tool-list check from the broker portal server (portal secret checked inside)
CREATE OR REPLACE FUNCTION public.mcp_write_access(p_secret text, p_at_digest bytea, p_resource text)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = '' AS $fn$
DECLARE
  v_conn uuid;
BEGIN
  IF public._mcp_secret_ok(p_secret) IS NOT TRUE THEN
    RETURN public._mcp_refuse('not_connected');
  END IF;
  SELECT c.id INTO v_conn
    FROM public.mcp_tokens t
    JOIN public.mcp_connections c ON c.id = t.connection_id
    JOIN public.mcp_settings s ON s.id
   WHERE t.token_sha256 = sha256(p_at_digest)
     AND octet_length(p_at_digest) = 32
     AND t.kind = 'access'
     AND t.expires_at > now()
     AND t.pepper_version = s.pepper_version
     AND s.enabled
     AND c.status = 'active'
     AND c.resource = p_resource;
  IF v_conn IS NULL THEN
    RETURN public._mcp_refuse('not_connected');
  END IF;
  RETURN jsonb_build_object('ok', true, 'write', public._mcp_conn_can_write(v_conn) IS TRUE);
END
$fn$;
REVOKE ALL ON FUNCTION public.mcp_write_access(text, bytea, text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.mcp_write_access(text, bytea, text) TO anon;

