                                                      p_resource text, p_scope text, p_state text, p_browser_binding_sha256 bytea, p_ip_sha256 bytea)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = '' AS $fn$
DECLARE
  v_b  text;
  v_id text;
BEGIN
