          CASE WHEN public._mcp_writes_on() THEN 'mcp:todos' ELSE 'mcp:read' END, p_state,                                            /*SCOPE:begin*/
          p_browser_binding_sha256, now() + interval '180 seconds');
  RETURN jsonb_build_object('ok', true, 'request_id', v_id, 'expires_in', 180);
