$fn$;$mutq$;
    SELECT md5(p.prosrc) = '2ccf12f955adbd53dd7c5dcec4fb050b' INTO ok FROM pg_proc p WHERE p.oid = to_regprocedure('public.mcp_authorize_begin(text,text,text,text,text,text,text,text,bytea,bytea)');
