  v_c0 := current_setting('request.jwt.claims', true);                                             /*CLAIMS:save*/
  v_s0 := current_setting('request.jwt.claim.sub', true);
  v_r0 := current_setting('request.jwt.claim.role', true);
  v_lt0 := current_setting('lock_timeout');
  BEGIN
    -- every lock wait in the block is bounded (the core's own head wait is 2 s too); a wait past it answers busy
    PERFORM set_config('lock_timeout', '2s', true);                                                /*LOCK:timeout*/
    PERFORM set_config('request.jwt.claims', jsonb_build_object('sub', g.user_id, 'role', 'authenticated')::text, true);
    PERFORM set_config('request.jwt.claim.sub', g.user_id::text, true);
    PERFORM set_config('request.jwt.claim.role', 'authenticated', true);
    IF p_tool = 'add_todo' THEN
      -- the next free place on the deal's live My items list, as the desktop adds one (0 for a new list)
      SELECT coalesce(max(t.sort_order) + 1, 0) INTO v_order                                       /*ADD:order*/
        FROM public.cloud_deal_checklist_items t
        JOIN public.cloud_deal_checklists c ON c.id = t.cloud_checklist_id
       WHERE c.cloud_deal_id = v_deal AND c.owner_user_id = g.user_id AND c.template_id = 'keepr:my-items'
         AND c.removed_at IS NULL AND c.purged_at IS NULL AND t.removed_at IS NULL AND t.purged_at IS NULL;
      v_ops := jsonb_build_array((v_ops -> 0) || jsonb_build_object('sort_order', v_order));
    END IF;
    v_res := public._cloud_todo_apply(g.user_id,
               jsonb_build_object('kind', 'ai_app', 'ref', g.connection_id::text,
                                  'label', CASE g.provider WHEN 'anthropic' THEN 'Claude' WHEN 'openai' THEN 'ChatGPT' END),   /*ACTOR:label*/
               v_ops);
    IF v_res ->> 'ok' IS DISTINCT FROM 'true' THEN
      v_first := CASE WHEN v_res ->> 'error' IN ('not_entitled', 'busy') THEN v_res ->> 'error' ELSE 'error' END;
      RAISE EXCEPTION USING ERRCODE = 'MC002', MESSAGE = 'mcp write refused';
    END IF;
    FOR v_r IN SELECT x FROM jsonb_array_elements(v_res -> 'results') x LOOP
      v_st := v_r ->> 'status';
      IF v_st IN ('applied', 'added', 'removed', 'restored') THEN
        v_wrote := v_wrote + 1; v_any := true;
      ELSIF v_st IN ('unchanged', 'already_added', 'already_removed', 'not_removed') THEN
        NULL;
      ELSE
        v_first := CASE WHEN v_st IN ('locked', 'not_allowed') THEN v_st
                        WHEN v_st = 'refused_removed' THEN 'is_removed'
                        WHEN v_st = 'not_restorable' AND p_tool = 'restore_todo' THEN 'not_restorable'
                        WHEN v_st IN ('not_found', 'not_restorable') THEN 'not_found'
                        WHEN v_st = 'rejected' THEN 'invalid_input'
                        ELSE 'error' END;
        RAISE EXCEPTION USING ERRCODE = 'MC002', MESSAGE = 'mcp write refused';                    /*WRITE:all_or_nothing*/
      END IF;
    END LOOP;
    -- a note the app could not have seen whole (shortened or masked when read) is not replaced
    IF v_note_op IS NOT NULL THEN
      SELECT h.old_value INTO v_old FROM public.cloud_todo_history h
       WHERE h.owner_user_id = g.user_id AND h.op_id = v_note_op AND h.part = 'note' AND h.kind = 'change' AND h.outcome = 'applied'
       ORDER BY h.id DESC LIMIT 1;
      IF jsonb_typeof(v_old) = 'string' AND public._mcp_clean(v_old #>> '{}', 1000) IS DISTINCT FROM (v_old #>> '{}') THEN   /*NOTE:shortened*/
        v_first := 'note_was_shortened';
        RAISE EXCEPTION USING ERRCODE = 'MC002', MESSAGE = 'mcp write refused';
      END IF;
    END IF;
    IF p_tool = 'add_todo' THEN
      v_item := (v_res -> 'results' -> 0 ->> 'cloud_id')::uuid;
    END IF;
    PERFORM set_config('request.jwt.claims', '', true);
    PERFORM set_config('request.jwt.claim.sub', coalesce(v_s0, ''), true);
    PERFORM set_config('request.jwt.claim.role', coalesce(v_r0, ''), true);
    PERFORM set_config('lock_timeout', v_lt0, true);                                               /*LOCK:restore*/
  EXCEPTION
    -- a failed block is rolled back with its claim settings; v_first says why
    WHEN SQLSTATE 'MC002' THEN NULL;
    WHEN lock_not_available THEN v_first := 'busy';
    -- _mcp_enter holds this connection's row; a turn-off holding the settings row then waits on it to disconnect
    -- the app. The write is the one that waited first, so it is the one refused; nothing of it is kept.
    WHEN deadlock_detected THEN v_first := 'busy';
    WHEN query_canceled THEN v_first := 'timeout';
    WHEN OTHERS THEN v_first := 'error';
  END;

  IF v_first IN ('not_connected', 'disabled', 'rate_limited', 'busy', 'read_only', 'not_entitled', 'invalid_input', 'not_found', 'timeout', 'error') THEN
    PERFORM public._mcp_finish(g.call_id, v_first, 0, v_t0);
    RETURN public._mcp_refuse(v_first);
  END IF;
  v_frame := jsonb_build_object(
    'kind', 'keepr.todo_change',
    'v', 1,
    'about', 'The answer to one change to a todo in the person''s Keepr account. status says what happened; locked, not_allowed, is_removed, not_restorable and note_was_shortened mean nothing was changed. item is the todo as it is now. Every change records this app''s name and shows in the Keepr desktop app.',
    'status', coalesce(v_first, CASE p_tool
                                  WHEN 'update_todo' THEN CASE WHEN v_any THEN 'applied' ELSE 'unchanged' END
                                  ELSE v_res -> 'results' -> 0 ->> 'status' END),
    'item', public._mcp_todo_item_out(g.user_id, v_item));
  PERFORM public._mcp_finish(g.call_id, CASE WHEN v_first IS NULL THEN 'ok' ELSE 'refused' END, CASE WHEN v_first IS NULL THEN v_wrote ELSE 0 END, v_t0);
  RETURN jsonb_build_object('ok', true, 'result', v_frame);
END
