DO $m_M09_partial_write_kept$
DECLARE v text; ok boolean;
BEGIN
  BEGIN
    EXECUTE $mutq$CREATE OR REPLACE FUNCTION public._mcp_todo_call(p_secret text, p_at_digest bytea, p_resource text, p_tool text, a jsonb)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path = '' AS $fn$
DECLARE
  g       public.mcp_gate;
  v_t0    timestamptz := clock_timestamp();
  v_b     text;
  v_uuid  text := '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$';
  v_item  uuid;
  v_deal  uuid;
  v_req   text := a ->> 'request_id';
  v_ch    jsonb := a -> 'changes';
  v_ops   jsonb := '[]'::jsonb;
  v_key   text;
  v_op    jsonb;
  v_note_op uuid;
  v_res   jsonb;
  v_r     jsonb;
  v_st    text;
  v_first text;
  v_wrote integer := 0;
  v_any   boolean := false;
  v_c0    text;
  v_s0    text;
  v_r0    text;
  v_lt0   text;
  v_old   jsonb;
  v_order integer;
  v_out   text;
  v_frame jsonb;
