  IF p_tool = 'update_todo' THEN
    FOREACH v_key IN ARRAY ARRAY['done', 'title', 'note', 'due_date'] LOOP
      CONTINUE WHEN NOT v_ch ? v_key;
      v_op := jsonb_build_object(
        'op_id', CASE WHEN v_req IS NULL THEN gen_random_uuid()
                      ELSE md5(concat_ws('|', 'mcp-todo', g.connection_id::text, p_tool, v_key, a::text))::uuid END,   /*REPLAY:op_id*/
